  "inlineSchema": "// ─────────────────────────────────────────────────────────\n// BRICOLE — Prisma Schema  (SQLite for local dev)\n// ─────────────────────────────────────────────────────────\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ───── Users ─────\nmodel User {\n  id               String   @id @default(uuid())\n  fullName         String\n  email            String   @unique\n  passwordHash     String\n  role             String   @default(\"particulier\") // particulier | pro | admin\n  phone            String?\n  isSuspended      Boolean  @default(false)\n  stripeCustomerId String?\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  professionalProfile ProfessionalProfile?\n  requests            Request[]\n  proposals           Proposal[]\n  quotes              Quote[]\n  sentMessages        Message[]            @relation(\"SentMessages\")\n  reviews             Review[]\n  appointments        Appointment[]\n  notifications       Notification[]\n  payments            Payment[]\n  conversationsAsPart Conversation[]       @relation(\"ParticulierConv\")\n  conversationsAsPro  Conversation[]       @relation(\"ProfessionalConv\")\n}\n\n// ───── Professional Profile ─────\nmodel ProfessionalProfile {\n  id                 String   @id @default(uuid())\n  userId             String   @unique\n  user               User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  bio                String?\n  metiers            String   @default(\"[]\") // JSON array of strings\n  ville              String?\n  experienceYears    Int      @default(0)\n  verified           Boolean  @default(false)\n  subscriptionStatus String   @default(\"inactive\") // active | inactive | cancelled\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @updatedAt\n\n  portfolio Portfolio[]\n}\n\n// ───── Portfolio ─────\nmodel Portfolio {\n  id          String              @id @default(uuid())\n  profileId   String\n  profile     ProfessionalProfile @relation(fields: [profileId], references: [id], onDelete: Cascade)\n  imageUrl    String\n  description String?\n  createdAt   DateTime            @default(now())\n}\n\n// ───── Categories ─────\nmodel Category {\n  id        Int      @id @default(autoincrement())\n  name      String   @unique\n  icon      String   @default(\"wrench\")\n  createdAt DateTime @default(now())\n\n  requests Request[]\n}\n\n// ───── Requests (Demandes) ─────\nmodel Request {\n  id            String   @id @default(uuid())\n  userId        String\n  user          User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  categoryId    Int\n  category      Category @relation(fields: [categoryId], references: [id])\n  typeBesoin    String\n  description   String\n  ville         String\n  codePostal    String?\n  budget        String?\n  urgence       String?\n  disponibilite String?\n  photoUrls     String   @default(\"[]\") // JSON array\n  status        String   @default(\"publiee\")\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  proposals     Proposal[]\n  quotes        Quote[]\n  conversations Conversation[]\n  reviews       Review[]\n}\n\n// ───── Proposals (Expressions d'intérêt) ─────\nmodel Proposal {\n  id             String   @id @default(uuid())\n  requestId      String\n  request        Request  @relation(fields: [requestId], references: [id], onDelete: Cascade)\n  professionalId String\n  professional   User     @relation(fields: [professionalId], references: [id], onDelete: Cascade)\n  message        String?\n  createdAt      DateTime @default(now())\n\n  @@unique([requestId, professionalId])\n}\n\n// ───── Quotes (Devis) ─────\nmodel Quote {\n  id             String   @id @default(uuid())\n  requestId      String\n  request        Request  @relation(fields: [requestId], references: [id], onDelete: Cascade)\n  professionalId String\n  professional   User     @relation(fields: [professionalId], references: [id], onDelete: Cascade)\n  description    String\n  mainOeuvre     Float\n  materiaux      Float\n  frais          Float    @default(0)\n  total          Float\n  dureeEstimee   String?\n  dateProposee   String?\n  status         String   @default(\"en_attente\") // en_attente | accepte | refuse\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n}\n\n// ───── Conversations ─────\nmodel Conversation {\n  id             String   @id @default(uuid())\n  requestId      String\n  request        Request  @relation(fields: [requestId], references: [id], onDelete: Cascade)\n  particulierId  String\n  particulier    User     @relation(\"ParticulierConv\", fields: [particulierId], references: [id], onDelete: Cascade)\n  professionalId String\n  professional   User     @relation(\"ProfessionalConv\", fields: [professionalId], references: [id], onDelete: Cascade)\n  createdAt      DateTime @default(now())\n\n  messages Message[]\n\n  @@unique([requestId, professionalId])\n}\n\n// ───── Messages ─────\nmodel Message {\n  id             String       @id @default(uuid())\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  senderId       String\n  sender         User         @relation(\"SentMessages\", fields: [senderId], references: [id], onDelete: Cascade)\n  content        String\n  createdAt      DateTime     @default(now())\n}\n\n// ───── Reviews (Avis) ─────\nmodel Review {\n  id                String   @id @default(uuid())\n  requestId         String\n  request           Request  @relation(fields: [requestId], references: [id], onDelete: Cascade)\n  particulierId     String\n  particulier       User     @relation(fields: [particulierId], references: [id], onDelete: Cascade)\n  qualite           Int\n  ponctualite       Int\n  prix              Int\n  communication     Int\n  professionnalisme Int\n  commentaire       String?\n  createdAt         DateTime @default(now())\n\n  @@unique([requestId, particulierId])\n}\n\n// ───── Appointments (Rendez-vous) ─────\nmodel Appointment {\n  id             String   @id @default(uuid())\n  userId         String\n  user           User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  type           String // \"Visite\", \"Intervention\", etc.\n  otherPartyName String\n  scheduledAt    DateTime\n  createdAt      DateTime @default(now())\n}\n\n// ───── Notifications ─────\nmodel Notification {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  text      String\n  isRead    Boolean  @default(false)\n  createdAt DateTime @default(now())\n}\n\n// ───── Payments ─────\nmodel Payment {\n  id              String   @id @default(uuid())\n  userId          String\n  user            User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  stripeSessionId String?  @unique\n  amount          Float\n  currency        String   @default(\"dzd\")\n  status          String   @default(\"pending\") // pending | completed | failed\n  description     String?\n  createdAt       DateTime @default(now())\n}\n",
